import requests
import json

# Try using an online PDF to text service
def pdf_to_text_online(pdf_url):
    try:
        # Use pdftotext.com API
        api_url = 'https://pdftotext.com/api/extract'
        data = {
            'url': pdf_url,
            'format': 'text'
        }
        response = requests.post(api_url, json=data, timeout=30)
        if response.status_code == 200:
            result = response.json()
            if 'text' in result:
                return result['text']
    except:
        pass

    # Try a different service - pdf2txt.org
    try:
        api_url = 'https://pdf2txt.org/api/convert'
        files = {'file': requests.get(pdf_url).content}
        response = requests.post(api_url, files=files, timeout=30)
        if response.status_code == 200:
            return response.text
    except:
        pass

    return None

# Download the PDF first
pdf_url = 'https://archive.org/download/unitedstatesstan14unit_4/unitedstatesstan14unit_4.pdf'
print('Attempting to extract text from PDF...')
text = pdf_to_text_online(pdf_url)

if text:
    print('Successfully extracted text from PDF')
    print('Text length:', len(text))

    # Look for key sections
    print('\\n=== SEARCHING FOR KEY SECTIONS ===')

    # Look for dried and dehydrated section
    if 'dried' in text.lower() or 'dehydrated' in text.lower():
        print('Found references to dried/dehydrated content')

        # Extract dried/dehydrated section
        lines = text.split('\\n')
        in_dried_section = False
        dried_items = []

        for i, line in enumerate(lines):
            line_lower = line.lower()
            if 'dried and dehydrated' in line_lower:
                in_dried_section = True
                print(f'Found dried section starting at line {i}')
                continue
            elif in_dried_section and line.strip() and not line_lower.startswith('dried'):
                # Look for items marked as dehydrated
                if 'dehydrated' in line_lower:
                    item_name = line.replace('dehydrated', '').strip()
                    if item_name:
                        dried_items.append(item_name)

        print(f'Found {len(dried_items)} dehydrated items:')
        for item in dried_items:
            print(f'  - {item}')

    # Look for frozen/chilled section
    if 'frozen' in text.lower() or 'chilled' in text.lower():
        print('\\nFound references to frozen/chilled content')

        # Extract frozen/chilled section
        in_frozen_section = False
        frozen_items = []
        chilled_items = []

        for i, line in enumerate(lines):
            line_lower = line.lower()
            if 'frozen' in line_lower and 'chilled' not in line_lower:
                in_frozen_section = True
                print(f'Found frozen section starting at line {i}')
                continue
            elif in_frozen_section and line.strip():
                # Check if line contains item name
                if len(line) > 10 and not line_lower.startswith('frozen'):
                    if 'frozen' in line_lower:
                        item_name = line.replace('frozen', '').strip()
                        if item_name and 'chilled' not in line_lower:
                            frozen_items.append(item_name)
                    elif 'chilled' in line_lower:
                        chilled_items.append(line.strip())

        print(f'Found {len(frozen_items)} frozen items (not chilled):')
        for item in frozen_items:
            print(f'  - {item}')

        print(f'Found {len(chilled_items)} chilled items:')
        for item in chilled_items:
            print(f'  - {item}')
else:
    print('Failed to extract text from PDF')
